#!/usr/bin/env python3
"""Static, dependency-free website builder. HTML contains all indexable content."""
from pathlib import Path
import json, shutil, re, os, unicodedata, hashlib
from html import escape as esc
from collections import defaultdict
from urllib.parse import quote
from tdt_tuning import notice as tuning_notice, guide as tuning_guide
from access_content import guide as access_guide, solutions as access_solutions
from connectivity_content import wifi_guide, shelly_guide
from lighting_content import guide as lighting_guide, local_card as lighting_local_card, directory_card as lighting_directory_card
from diagnostics_content import local_focus as diagnostic_local_focus, service_section as diagnostic_service_section, satellite_platforms
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'dist'
BASE='https://antenasnorte24.com'
PREVIEW=os.getenv('CONTEXT','') in ('deploy-preview','branch-deploy')
S=json.loads((ROOT/'data/services.json').read_text())
P=json.loads((ROOT/'data/provinces.json').read_text())
M=json.loads((ROOT/'data/municipios.json').read_text())
LOCAL_CONTEXT=json.loads((ROOT/'data/contexto-local.json').read_text())
NUCLEI=json.loads((ROOT/'data/nucleos-ine.json').read_text())
D=json.loads((ROOT/'data/madrid-distritos.json').read_text())['districts']
CITIES=json.loads((ROOT/'data/zonas-capitales.json').read_text())['cities']
DECISION_GUIDES=json.loads((ROOT/'data/guias-decision.json').read_text())
FAULTS=json.loads((ROOT/'data/averias.json').read_text())
CORE_SERVICES=[s for s in S if s['slug'] not in {'sintonizacion-televisores','control-accesos','instalacion-wifi','domotica-shelly'}]
PHONE={'norte':('670042626','670 042 626'),'madrid':('614789945','614 78 99 45')}
BY_PROVINCE={p['id']:p for p in P}
def slug(s):
 s=unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower()
 return re.sub(r'[^a-z0-9]+','-',s).strip('-')
def display(s):
 # Preserve official bilingual names; move the official trailing article for readability.
 m=re.match(r'^(.*), (El|La|Los|Las|el|la|los|las)$',s)
 return (m.group(2).capitalize()+' '+m.group(1)) if m else s
for m in M:
 m['name']=display(m['nombre']);m['slug']=slug(m['name']);m['p']=BY_PROVINCE[m['provincia_id']];m['url']='/'+m['p']['slug']+'/'+m['slug']+'/'
assert len({m['url'] for m in M})==len(M),'Municipality URL collision'
BY_MUNICIPALITY={m['municipio_id']:m for m in M}
for p in P:p['towns']=sorted([m for m in M if m['provincia_id']==p['id']],key=lambda m:slug(m['name']))
for d in D:d['slug']=slug(d['name']);d['url']='/madrid/distritos/'+d['slug']+'/'
for c in CITIES:
 c['municipality']=next(m for m in M if m['municipio_id']==c['municipality_id'])
 for area in c['zones']:area['id']='zona-'+slug(area['name']);area['url']=c['municipality']['url']+'#'+area['id']
CITY_BY_ID={c['municipality_id']:c for c in CITIES}
if OUT.exists():shutil.rmtree(OUT)
OUT.mkdir();shutil.copytree(ROOT/'assets',OUT/'assets',ignore=shutil.ignore_patterns('*.original'))
# A content fingerprint prevents cached CSS/JS from mixing with newly deployed HTML.
ASSET_URLS={}
for asset in ('style.css','app.js'):
 source=ROOT/'assets'/asset
 fingerprint=hashlib.sha256(source.read_bytes()).hexdigest()[:12]
 target=f'{source.stem}.{fingerprint}{source.suffix}'
 shutil.copyfile(source,OUT/'assets'/target)
 ASSET_URLS[asset]='/assets/'+target

pages={};groups=defaultdict(list)
ICON='''<svg viewBox="0 0 48 54" fill="none" aria-hidden="true"><path d="M24 49V22M14 49h20M17 37h14M9 19l30-9M8 11l4 15M17 8l4 15M26 5l4 15M35 2l4 15" stroke="currentColor" stroke-width="3" stroke-linecap="round"/><circle cx="24" cy="27" r="4" fill="#8e294b"/></svg>'''
LOGO=f'<a class="logo" href="/" aria-label="Antenas Norte 24, inicio">{ICON}<span>ANTENAS<br>NORTE <b>24</b><small>SEÑAL · ACCESO · CONEXIÓN</small></span></a>'
def wa(zone,text='Hola, quiero consultar un servicio de Antenas Norte 24.'):
 return 'https://wa.me/34'+PHONE[zone][0]+'?text='+quote(text)
def buttons(zone='norte',text=None):
 return f'<div class="actions"><a class="btn btn-dark" href="tel:+34{PHONE[zone][0]}">Llamar · {PHONE[zone][1]}</a><a class="btn btn-wa" href="{wa(zone,text or "Hola, quiero consultar un servicio de Antenas Norte 24.")}">Consultar por WhatsApp →</a></div>'
def img(service,loading='lazy'):
 return f'<img src="/assets/{service["image"]}" alt="{esc(service["alt"])}" width="640" height="480" loading="{loading}" decoding="async">'
def check(items):return '<ul class="check-list">'+''.join('<li>'+esc(i)+'</li>' for i in items)+'</ul>'
def faq(items):
 return '<div class="faq-list">'+''.join(f'<details><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q,a in items)+'</div>'
def breadcrumbs(items):
 return '<nav class="crumbs wrap" aria-label="Ruta de navegación"><a href="/">Inicio</a>'+''.join(' / '+(f'<a href="{u}">{esc(t)}</a>' if u else f'<span aria-current="page">{esc(t)}</span>') for t,u in items)+'</nav>'
def service_cards(exclude=None):
 cards=[]
 for i,s in enumerate(S):
  if s['slug']==exclude:continue
  cards.append(f'<article class="service-card"><a class="service-image service-image-numbered" href="/servicios/{s["slug"]}/" aria-label="Ver {esc(s["title"])}"><span class="service-num">{i+1:02d} / SERVICIO</span>{img(s)}</a><div class="service-body"><h3>{esc(s["title"])}</h3><p>{esc(s.get("card_intro",s["intro"]))}</p><a class="text-link" href="/servicios/{s["slug"]}/">Ver el servicio</a></div></article>')
 return '<div class="services-grid">'+''.join(cards)+lighting_directory_card()+'</div>'
def brand_url(name):return {'Reyee':'/servicios/instalacion-wifi/','Shelly':'/servicios/domotica-shelly/'}.get(name,'/marcas/'+slug(name)+'/')
def local_service_group(key):
 return 'acceso' if key in ['porteros-automaticos','videoporteros','control-accesos'] else 'red' if key in ['instalacion-starlink','instalacion-wifi','domotica-shelly'] else 'senal'
def local_service_filters():
 return '<nav class="local-service-filters" aria-label="Filtrar servicios de esta localidad">'+''.join(f'<button type="button" data-service-filter="{key}" aria-controls="servicios-locales" aria-pressed="{str(key=="todos").lower()}">{label}</button>' for key,label in [('todos','Todos los servicios'),('senal','Televisión y antenas'),('acceso','Porteros y accesos'),('red','Internet, domótica y luz')])+'</nav>'
def local_product(s):
 product=dict(s)
 product['image']=s.get('local_image',s['image'])
 product['alt']=s.get('local_alt',s['alt'])
 caption=s.get('local_caption')
 if not caption:
  caption='Ilustración del servicio' if product['image'].endswith('.svg') else 'Equipo de catálogo · '+s['brands'][0]
 return '<figure class="local-product-thumb">'+img(product)+'<figcaption>'+esc(caption)+'</figcaption></figure>'
def lock_product():
 return local_product({'image':'abrepuertas-fermax.webp','alt':'Abrepuertas eléctrico Fermax de catálogo con armadura larga','brands':['Fermax']})
def provinces_links():return '<div class="province-links">'+''.join(f'<a href="/{p["slug"]}/">{p["name"]}</a>' for p in P)+'</div>'
def townlist(towns):
 return '<ul class="town-list">'+''.join(f'<li><a href="{t["url"]}">Antenista en {esc(t["name"])}</a></li>' for t in towns)+'</ul>'
def district_list():
 return '<ul class="town-list">'+''.join(f'<li><a href="{d["url"]}">Antenista en {esc(d["name"])}</a></li>' for d in D)+'</ul>'
def district_directory(inline=False):
 if inline:
  return '<div id="distritos"><h3>Distritos de Madrid capital</h3>'+district_list()+'<p style="margin:20px 0 35px"><a class="text-link" href="/madrid/distritos/">Ver todos los servicios por distritos</a></p><h3>Municipios de la Comunidad de Madrid</h3></div>'
 return '<section class="section" id="distritos"><div class="wrap"><span class="eyebrow">MADRID CAPITAL</span><h2>Encuentra tu distrito.</h2><p>Los 21 distritos de Madrid, con el contacto de la ciudad: <a href="tel:+34614789945"><strong>614 78 99 45</strong></a>.</p>'+district_list()+'<p style="margin-top:24px"><a class="text-link" href="/madrid/distritos/">Ver servicios por distritos</a></p></div></section>'
def city_zone_links(c):
 return '<ul class="town-list">'+''.join(f'<li><a href="{a["url"]}">Antenista en {esc(a["name"])} · {esc(c["name"])}</a></li>' for a in c['zones'])+'</ul>'
def province_city_zones(p):
 cities=[c for c in CITIES if c['municipality']['p']['slug']==p['slug']]
 return ''.join(f'<div class="capital-directory"><span class="eyebrow">DENTRO DE LA CAPITAL</span><h3>{c["type"].capitalize()} de {esc(c["name"])}.</h3>{city_zone_links(c)}<p class="small">¿Buscas otro municipio? Continúa con el listado alfabético de {p["name"]}.</p></div>' for c in cities)
def city_zones(c):
 cards=''
 for a in c['zones']:
  place=a['name']+', '+c['name']
  area_text=f'<p class="small">{esc(a["areas"])}</p>' if a['areas'] else ''
  cards+=f'<details class="urban-zone" id="{a["id"]}"><summary><span>{esc(a["name"])}</span><span aria-hidden="true">+</span></summary><div class="urban-zone-body">{area_text}<p>Para consultar antenas TDT, porteros automáticos o reparación de videoportero en {esc(a["name"])}, indica calle, número y si afecta a tu vivienda o a más vecinos.</p><a class="btn btn-wa" href="{wa("norte","Hola, necesito un servicio en "+place+". Mi consulta es: ")}" rel="noopener">Consultar en {esc(a["name"])} →</a></div></details>'
 return f'<section class="section" id="zonas-ciudad"><div class="wrap"><div class="split-heading"><div><span class="eyebrow">TU ZONA EN LA CIUDAD</span><h2>Antenas y porteros automáticos<br>por {c["type"]} de {esc(c["name"])}.</h2></div><p>Viviendas individuales y comunidades. Abre tu zona para preparar el aviso. Contacto Norte: <a href="tel:+34670042626">670 042 626</a>.</p></div><div class="urban-grid">{cards}</div><p class="small urban-note">Si no reconoces tu zona, basta con indicar la dirección. Confirmamos disponibilidad y desplazamiento antes de concertar la visita.</p><p class="small">Nombres y agrupaciones: <a href="{esc(c["source"],quote=True)}" rel="noopener">fuente municipal de {esc(c["name"])} ↗</a>. No son municipios independientes ni ubicaciones de oficinas.</p></div></section>'
def finder(selected=''):
 options=''.join(f'<option value="{p["slug"]}" {"selected" if p["slug"]==selected else ""}>{p["name"]}</option>' for p in P)
 return f'''<div class="finder"><h3>Encuentra tu localidad</h3><p class="small">Busca tu pueblo o entra en el directorio de tu provincia.</p><div class="finder-controls"><div class="field"><label for="town-province">Provincia</label><select id="town-province"><option value="">Todas las provincias</option>{options}</select></div><div class="field"><label for="town-search">Pueblo, ciudad o distrito</label><input id="town-search" type="search" placeholder="Por ejemplo: Zalla, Lerma o Torrelaguna" autocomplete="off" aria-controls="town-results"></div></div><p id="search-status" class="status" role="status" aria-live="polite"></p><ul id="town-results" class="search-results"></ul><noscript><p>Accede al listado completo desde los enlaces de provincia que aparecen en esta página.</p></noscript></div>'''
def contact(zone='norte',province='',town='',service='',nuclei=None):
 options=''.join(f'<option value="{p["slug"]}" {"selected" if p["slug"]==province else ""}>{p["name"]}</option>' for p in P)
 if not province and zone=='madrid':options=options.replace('value="madrid"','value="madrid" selected')
 nucleus_field=''
 if nuclei:
  nucleus_field='<div class="field"><label for="form-nucleus">Núcleo, entidad o barrio (opcional)</label><input id="form-nucleus" name="nucleus" data-municipality="'+esc(town,quote=True)+'" data-province="'+esc(province,quote=True)+'" list="form-nuclei" maxlength="120" placeholder="Escribe o elige la zona del inmueble"><datalist id="form-nuclei">'+''.join('<option value="'+esc(unit['name'],quote=True)+'"></option>' for unit in nuclei)+'</datalist></div>'
 services=''.join(f'<option {"selected" if s["title"]==service else ""}>{esc(s["title"])}</option>' for s in S)
 services+=f'<option {"selected" if service=="Iluminación LED y sensores" else ""}>Iluminación LED y sensores</option>'
 return f'''<section class="section dark" id="contacto"><div class="wrap contact-grid"><div><span class="eyebrow">HABLEMOS DE TU INSTALACIÓN</span><h2>Cuéntanos qué necesitas. Vamos al detalle.</h2><p class="lead">Una avería, una instalación nueva o la renovación de tu comunidad. Indica dónde estás y te orientamos sobre el siguiente paso.</p>{check(['Trato directo para explicar la incidencia.','Viviendas particulares y comunidades de propietarios.','Puedes adjuntar fotos cuando se abra WhatsApp.'])}<p class="small">La disponibilidad, el desplazamiento y las condiciones del trabajo se confirman antes de concertar la visita.</p><p><a href="tel:+34670042626">Zona norte · 670 042 626</a><br><a href="tel:+34614789945">Madrid · 614 78 99 45</a></p></div><form id="contact-form"><h3>Prepara tu consulta</h3><div class="form-row"><div class="field"><label for="form-service">¿Qué servicio necesitas?</label><select id="form-service" name="service" required>{services}<option>Reparación de cerraduras eléctricas y abrepuertas</option><option>Quiero que reviséis mi caso</option></select></div><div class="field"><label for="form-province">Provincia</label><select id="form-province" name="province" required>{options}</select></div></div><div class="form-row"><div class="field"><label for="form-town">Localidad</label><input id="form-town" name="town" value="{esc(town,quote=True)}" list="form-town-list" autocomplete="address-level2" maxlength="120" required><datalist id="form-town-list"></datalist></div><div class="field"><label for="form-property">Tipo de inmueble</label><select id="form-property" name="property"><option>Vivienda individual / piso</option><option>Chalet / unifamiliar</option><option>Comunidad de vecinos</option><option>Casa rural / caserío</option><option>Local / negocio</option></select></div></div><div class="form-row"><div class="field"><label for="form-name">Tu nombre</label><input id="form-name" name="name" autocomplete="given-name" maxlength="80" required></div><div class="field"><label for="form-phone">Teléfono de contacto</label><input id="form-phone" type="tel" name="phone" autocomplete="tel" inputmode="tel" minlength="9" maxlength="20" pattern="[+0-9 ()-]{{9,20}}" required></div></div>{nucleus_field}<div class="field"><label for="form-message">¿Qué ocurre? <span class="muted">(opcional)</span></label><textarea id="form-message" name="message" maxlength="1500" placeholder="Por ejemplo: fallan varios canales en todo el edificio."></textarea></div><div class="honeypot" aria-hidden="true"><label>Deja este campo vacío<input name="website" tabindex="-1" autocomplete="off"></label></div><div id="form-destination" class="form-destination" aria-live="polite">{PHONE[zone][1]}</div><label class="consent"><input type="checkbox" name="privacy" required><span>He leído la <a href="/privacidad/">política de privacidad</a> y quiero enviar esta consulta por WhatsApp.</span></label><button class="btn btn-wa" type="submit">Continuar en WhatsApp →</button><p class="form-note">Se abrirá WhatsApp con el mensaje preparado. Tú decides cuándo enviarlo. Este formulario no guarda los datos en la web.</p><noscript><p>Para preparar el mensaje activa JavaScript o <a href="{wa(zone)}">consulta directamente por WhatsApp</a>.</p></noscript></form></div></section>'''
def coverage_map():
 return (ROOT/'assets/mapa-cobertura.svg').read_text()
def map_section():return f'''<section class="section" id="mapa"><div class="wrap map-layout"><div>{coverage_map()}<p class="small">Mapa orientativo de las provincias de servicio. Los puntos no representan oficinas.</p></div><div><span class="eyebrow">CERCA DE TU LOCALIDAD</span><h2>Zona norte.<br>También en Madrid.</h2><p>Bizkaia, Álava, Gipuzkoa, Burgos, Cantabria y La Rioja comparten el contacto de la zona norte. Madrid dispone de atención por su propio número.</p>{provinces_links()}<p class="small" style="margin-top:20px">Consulta la disponibilidad en tu municipio y las condiciones de desplazamiento.</p></div></div></section>'''
def layout(path,title,description,body,zone='norte',crumb=None,group='principal',schema=None,noindex=False):
 canonical=BASE+path
 # The stylesheet adds the text-link arrow; remove a literal trailing copy.
 body=re.sub(r'(<a\b[^>]*class="[^"]*\btext-link\b[^"]*"[^>]*>)(.*?)(</a>)',lambda m:m[1]+re.sub(r'\s*→\s*$','',m[2])+m[3],body,flags=re.S)
 structured=[{'@context':'https://schema.org','@type':'Organization','@id':BASE+'/#organization','name':'Antenas Norte 24','url':BASE+'/', 'logo':BASE+'/assets/favicon.svg','contactPoint':[{'@type':'ContactPoint','telephone':'+34670042626','contactType':'customer service','areaServed':['Bizkaia','Álava','Gipuzkoa','Burgos','Cantabria','La Rioja'],'availableLanguage':'es'},{'@type':'ContactPoint','telephone':'+34614789945','contactType':'customer service','areaServed':'Madrid','availableLanguage':'es'}]}, {'@context':'https://schema.org','@type':'WebPage','name':title,'description':description,'url':canonical,'inLanguage':'es','isPartOf':{'@id':BASE+'/#website'}}]
 if crumb:
  entries=[('Inicio','/')]+crumb
  structured.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':BASE+(u or path)} for i,(n,u) in enumerate(entries)]})
 if schema:structured.append(schema)
 robots='noindex,follow' if PREVIEW or noindex else 'index,follow,max-image-preview:large'
 header=f'''<a class="skip" href="#contenido">Saltar al contenido</a><div class="topbar"><div class="wrap"><a class="urgent-link" href="tel:+34{PHONE[zone][0]}"><span class="urgent-dot" aria-hidden="true"></span><strong>Urgencias 24 horas</strong><span class="urgent-arrow" aria-hidden="true">→</span></a><span class="extra">Antenas Norte 24 · Viviendas y comunidades</span></div></div><header class="header"><div class="wrap header-inner">{LOGO}<button class="menu-button" type="button" aria-controls="main-nav" aria-expanded="false">Menú ☰</button><nav class="nav" id="main-nav" aria-label="Menú principal"><a href="/servicios/">Servicios</a><a href="/comunidades/">Comunidades</a><a href="/cobertura/">Localidades</a><a href="/guias/">Averías y guías</a><a class="nav-cta" href="#contacto">Consultar servicio →</a></nav></div></header>'''
 footer=f'''<footer class="footer"><div class="wrap"><div class="footer-grid"><div>{LOGO}<p>Antenas, amplificación y sistemas de acceso.<br>Instalación y reparación para tu vivienda o comunidad.</p><p><a href="tel:+34670042626">Zona norte · 670 042 626</a><br><a href="tel:+34614789945">Madrid · 614 78 99 45</a></p></div><div><h3>Servicios</h3><ul>{''.join(f'<li><a href="/servicios/{s["slug"]}/">{s["title"]}</a></li>' for s in S)}</ul></div><div><h3>Zona de servicio</h3><ul>{''.join(f'<li><a href="/{p["slug"]}/">Antenista en {p["name"]}</a></li>' for p in P)}</ul><a href="/comunidades/">Comunidades de propietarios</a></div></div><div class="footer-bottom"><span>© Antenas Norte 24 · D.C.G. · antenasnorte24.com</span><span><a href="/aviso-legal/">Aviso legal</a> · <a href="/privacidad/">Privacidad</a> · <a href="/cookies/">Cookies</a></span></div></div></footer><aside class="bottom-contact" aria-label="Contacto rápido"><label for="contact-zone">Tu zona</label><select id="contact-zone" aria-label="Seleccionar zona de contacto"><option value="norte" {"selected" if zone=="norte" else ""}>Norte</option><option value="madrid" {"selected" if zone=="madrid" else ""}>Madrid</option></select><span id="active-phone" class="contact-label">{PHONE[zone][1]}</span><a class="btn btn-dark" data-call href="tel:+34{PHONE[zone][0]}">Llamar</a><a class="btn btn-wa" data-whatsapp href="{wa(zone)}">WhatsApp →</a></aside>'''
 doc=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description,quote=True)}"><meta name="robots" content="{robots}"><meta name="theme-color" content="#29232b"><link rel="canonical" href="{canonical}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><link rel="stylesheet" href="{ASSET_URLS['style.css']}"><meta property="og:type" content="website"><meta property="og:locale" content="es_ES"><meta property="og:site_name" content="Antenas Norte 24"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}/assets/social.jpg"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">{json.dumps(structured,ensure_ascii=False).replace('<',chr(92)+'u003c')}</script><script defer src="{ASSET_URLS['app.js']}"></script></head><body data-zone="{zone}">{header}{breadcrumbs(crumb) if crumb else ''}<main id="contenido">{body}</main>{footer}</body></html>'''
 target=OUT/(path.strip('/')+'/index.html' if path!='/' else 'index.html');target.parent.mkdir(parents=True,exist_ok=True);target.write_text(doc)
 if not noindex:pages[path]=doc;groups[group].append(path)

def hero_small(title,intro,zone='norte',service=None,eyebrow='INSTALACIÓN Y REPARACIÓN'):
 visual=f'<div class="product-panel">{img(service,"eager")}<p class="small">{esc(service.get("image_caption","Imagen de catálogo · "+service["brands"][0]))}</p></div>' if service else ''
 return f'<section class="page-hero"><div class="wrap {"page-hero-grid" if service else ""}"><div><span class="eyebrow">{eyebrow}</span><h1>{title}</h1><p class="lead">{intro}</p>{buttons(zone)}</div>{visual}</div></section>'

def decision_help(service):
 if service in ['antenas-tdt','amplificacion-tdt-satelite']:
  return '<section class="section choice-section" id="interferencias-tdt"><div class="wrap"><span class="eyebrow">CUANDO LA TDT FALLA A RATOS</span><h2>¿Falta señal, sobra nivel<br>o hay una interferencia?</h2><div class="choice-grid"><article class="choice-card"><h3>No lo dice el porcentaje de la TV</h3><p>El indicador del receptor ayuda a observar cambios, pero no identifica por sí solo la causa. Hay que comparar nivel y calidad en distintos puntos de la instalación.</p></article><article class="choice-card"><h3>Un filtro no siempre es la solución</h3><p>Las señales móviles próximas a la banda de televisión pueden requerir filtrado. Antes se mide su influencia y se comprueba si los equipos ya incorporan protección; los mismos síntomas pueden tener otro origen.</p></article><article class="choice-card"><h3>Amplificar más puede empeorarlo</h3><p>Si la entrada es inadecuada o existe saturación, aumentar ganancia no resuelve el fallo. La intervención puede requerir revisar conexiones, alimentación, orientación o ajustes, según las mediciones.</p></article></div><p class="small" style="margin-top:24px">¿Faltan canales tras una reorganización? <a href="/servicios/sintonizacion-televisores/">Cómo resintonizar y ordenar la televisión</a>. Referencia técnica: <a href="https://www.televes.com/downloadfile/PSH01232419_0_Espanol_596597.pdf/596112_es_ES_product_sheet_PSH01232419.pdf">Televes: análisis de interferencias LTE antes de decidir el filtrado</a>.</p></div></section>'
 if service not in ['porteros-automaticos','videoporteros']:return ''
 choices=[('Reparar el elemento averiado','Si el sistema cubre lo que necesitas, interesa localizar la pieza que falla y comprobar si existe recambio. Un problema de apertura no obliga por sí solo a cambiar todo el portal.'),('Cambiar un terminal compatible','Puede ser una opción cuando la avería está en una vivienda. Antes se identifica el sistema común: no basta con elegir otro telefonillo o monitor que se parezca.'),('Estudiar una renovación','Tiene sentido valorarla si faltan recambios o se necesitan funciones que el sistema actual no admite. La decisión incluye placa, terminales, cableado y necesidades de la comunidad.')]
 cards=''.join(f'<article class="choice-card"><span class="eyebrow">OPCIÓN {i}</span><h3>{esc(t)}</h3><p>{esc(d)}</p></article>' for i,(t,d) in enumerate(choices,1))
 return '<section class="section choice-section" id="reparar-o-renovar"><div class="wrap"><span class="eyebrow">ANTES DE ELEGIR UN EQUIPO</span><h2>¿Reparar, cambiar un terminal<br>o renovar el sistema?</h2><p class="choice-intro">La opción adecuada depende del diagnóstico y de las funciones que realmente necesitas.</p><div class="choice-grid">'+cards+'</div><div class="decision-links"><a href="/guias/presupuesto-videoportero-comunidad/">Qué comparar en un presupuesto →</a><a href="/guias/videoportero-wifi-llamadas-movil/">Qué necesitas para atender desde el móvil →</a></div></div></section>'

def fault_help(zone='norte',place='',service=None):
 items=[f for f in FAULTS if not service or f['service']==service]
 if not items:return ''
 cards=''
 for f in items:
  message='Hola, necesito ayuda'+(' en '+place if place else '')+'. '+f['title']+'.'
  cards+=f'<details class="fault-item"><summary><span class="fault-tag">{esc(f["tag"])}</span><span>{esc(f["title"])}</span><span class="fault-plus" aria-hidden="true">+</span></summary><div class="fault-answer"><p>{esc(f["description"])}</p><div class="fault-links"><a href="/guias/{f["slug"]}/">Qué comprobar y posibles causas →</a><a href="{wa(zone,message)}" rel="noopener">Consultar esta avería ↗</a></div></div></details>'
 return f'<section class="section fault-section" id="averias"><div class="wrap"><div class="fault-heading"><div><span class="eyebrow">EMPIEZA POR EL SÍNTOMA</span><h2>¿Qué ha dejado<br>de funcionar?</h2></div><p>Elige lo que te ocurre. Te ayudamos a preparar el aviso'+(' en '+esc(place) if place else '')+f', sin cambiar piezas a ciegas.</p></div><div class="fault-grid">{cards}</div><p class="fault-footnote">Orientación inicial, sin diagnóstico a distancia. No necesitas abrir equipos ni subir al tejado.</p></div></section>'

def local_fault_links():
 links=''.join(f'<a href="/guias/{f["slug"]}/">{esc(f["title"])} <span aria-hidden="true">→</span></a>' for f in FAULTS)
 return '<section class="section compact-faults"><div class="wrap"><span class="eyebrow">GUÍAS PARA PREPARAR EL AVISO</span><h2>Busca el síntoma de tu instalación.</h2><p>Comprobaciones de uso y datos que conviene indicar antes de pedir una revisión.</p><nav class="local-fault-links" aria-label="Guías de averías">'+links+'</nav></div></section>'

